-- ============================================================================
-- Risk Radar - seed data (GENERATED by generate_seed.py, do not edit by hand)
-- Run after: schema.sql, schema_weights_addendum.sql, spatial-model.sql
--
-- Supersedes seed_indicator_catalog_final.sql, which was written against
-- assumed column names and did not match schema.sql.
--
-- Foreign keys are resolved by CODE in subqueries, so this file is
-- order-independent and safe to re-run (every INSERT is ON CONFLICT-guarded).
-- ============================================================================
BEGIN;

-- 1. Provinces -------------------------------------------------------------
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name;

-- 2. Hazard types ----------------------------------------------------------
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name;

-- 3. Sectors ---------------------------------------------------------------
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name;

-- 4. Subsectors ------------------------------------------------------------
ON CONFLICT (sector_id, code) DO UPDATE SET name = EXCLUDED.name;

-- 5. Indicator catalog (174 canonical variables) ---------------------------
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name, domain = EXCLUDED.domain,
    status = 'active', period_aggregation = EXCLUDED.period_aggregation;

-- 6. Aliases (legacy codes + sheet-label variants) -------------------------
ON CONFLICT DO NOTHING;

-- 7. Vulnerability profiles (province x sector x hazard) -------------------
ON CONFLICT (code) DO NOTHING;

-- 8. Profile membership ----------------------------------------------------
--    weight_pct NULL = variable belongs to the profile but has no weight yet;
--    it is set in the app at import. See addendum rev 4.
ON CONFLICT (profile_id, domain, indicator_id) DO NOTHING;

COMMIT;